"""Refresh the installed skill from the master SKILL.md, and install the agents. Run after EVERY change to SKILL.md or agents/:
    python tools/refresh_installed_skill.py
Master = this folder. Installed copy = ~/.claude/skills/cartoon-3d-short/SKILL.md: same body, absolute paths, its own name + description (kept from the installed file on every refresh).
Agents: every agents/*.md is copied to ~/.claude/agents/ with the skill's paths made absolute, so the camera-director and storyboard-judge agents can be called from any folder."""
import os, re, glob, subprocess, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))).replace("\\", "/")
DST = os.path.join(os.path.expanduser("~"), ".claude", "skills", "cartoon-3d-short", "SKILL.md")
FRONT = re.compile(r"\A---\n(.*?)\n---\n", re.S)
subprocess.run([sys.executable, os.path.join(os.path.dirname(os.path.abspath(__file__)), "slice_rules.py")], check=True, stdout=subprocess.DEVNULL)   # CB_RULES section 11, T1: fresh rule slices on every refresh
master = open(os.path.join(ROOT, "SKILL.md"), encoding="utf-8").read()
installed = open(DST, encoding="utf-8").read()
front = FRONT.match(installed).group(0); body = master[FRONT.match(master).end():]
ABS = lambda s: re.sub(r"(?<![\w/\\.:-])(templates|tools|references|library|agents|rules)/", ROOT + r"/\1/", s)
body = re.sub(r"(?<![\w/\\.:-])(templates|tools|references|library|episodes|rick-shorts|agents|rules)/", ROOT + r"/\1/", body)
body = re.sub(r"\]\((WORKFLOW|DENSITY_RULES|HANDOFF|FILE_GUIDE|CINEMATOGRAPHY|CB_RULES)\.md\)", lambda m: "](%s/%s.md)" % (ROOT.replace(" ", "%20"), m.group(1)), body)
note = "\n> **This is an installed copy.** The master copy is `%s/SKILL.md`. Do not edit this file: after any change to the master, run `python \"%s/tools/refresh_installed_skill.py\"`.\n" % (ROOT, ROOT)
open(DST, "w", encoding="utf-8", newline="\n").write(front + note + body)
print("refreshed", DST, len(body))
ADST = os.path.join(os.path.expanduser("~"), ".claude", "agents"); os.makedirs(ADST, exist_ok=True)
for p in sorted(glob.glob(os.path.join(ROOT, "agents", "*.md"))):
    a = open(p, encoding="utf-8").read(); m = FRONT.match(a)
    a = m.group(0) + ABS(a[m.end():]).replace("`CINEMATOGRAPHY.md`", "`%s/CINEMATOGRAPHY.md`" % ROOT).replace("`SKILL.md`", "`%s/SKILL.md`" % ROOT)
    open(os.path.join(ADST, os.path.basename(p)), "w", encoding="utf-8", newline="\n").write(a); print("agent", os.path.basename(p))
